fn array_sum(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x + y)
     .collect()
}

fn main() {
    let v1 = vec![1, 2, 3];
    let v2 = vec![4, 5, 6];
    let result = array_sum(v1, v2);
    println!("{:?}", result); // prints [5, 7, 9]
}